# ============================================================
# STEP 2: Load NIC ATM Dataset
# ============================================================

import pandas as pd
import numpy as np
import geopandas as gpd
import folium

from folium.plugins import HeatMap, MarkerCluster
from IPython.display import display

CSV_FILE = "/content/telangana_nic_atm_9642.csv"

df = pd.read_csv(CSV_FILE)

print("Dataset shape:", df.shape)
print("\nColumns:")
print(df.columns.tolist())

display(df.head())

# ============================================================
# STEP 3: Clean ATM data
# ============================================================

atm = df.copy()

# Standardize column names
atm.columns = (
    atm.columns
    .str.strip()
    .str.lower()
)

# Clean string fields
string_columns = [
    "bank_name",
    "atm_cd",
    "stname",
    "dtname",
    "atm_city",
    "atm_pin_cd"
]

for col in string_columns:
    atm[col] = atm[col].fillna("").astype(str).str.strip()

# Convert coordinates to numeric
atm["atm_lat"] = pd.to_numeric(atm["atm_lat"], errors="coerce")
atm["atm_long"] = pd.to_numeric(atm["atm_long"], errors="coerce")

print("Original records:", len(atm))

# Remove missing coordinates
atm = atm.dropna(subset=["atm_lat", "atm_long"])

# Telangana approximate geographic bounds
# Used only as a sanity check, not as an official boundary.
valid_coords = (
    atm["atm_lat"].between(15.5, 20.5)
    &
    atm["atm_long"].between(77.0, 82.0)
)

invalid = atm[~valid_coords].copy()

atm = atm[valid_coords].copy()

print("Valid geographic records:", len(atm))
print("Removed invalid coordinates:", len(invalid))

print("\nInvalid coordinate records:")
display(invalid)

# ============================================================
# STEP 4: Inspect duplicate ATM IDs
# ============================================================

duplicate_ids = atm[
    atm["atm_cd"].duplicated(keep=False)
].sort_values("atm_cd")

print("Duplicate ATM IDs:", duplicate_ids["atm_cd"].nunique())

display(duplicate_ids.head(50))

# ============================================================
# STEP 5: Create GeoDataFrame
# ============================================================

gdf = gpd.GeoDataFrame(
    atm,
    geometry=gpd.points_from_xy(
        atm["atm_long"],
        atm["atm_lat"]
    ),
    crs="EPSG:4326"
)

print(gdf.crs)
print("GIS points:", len(gdf))

display(gdf.head())

# ============================================================
# STEP 6: Export cleaned ATM data as GeoJSON
# ============================================================

geojson_file = "/content/telangana_atms_clean.geojson"

gdf.to_file(
    geojson_file,
    driver="GeoJSON"
)

print("GeoJSON created:")
print(geojson_file)

# ============================================================
# STEP 7: Interactive Telangana ATM map
# ============================================================

from folium.plugins import MarkerCluster

# Center roughly around Telangana
m = folium.Map(
    location=[17.9, 79.5],
    zoom_start=7,
    tiles="OpenStreetMap"
)

cluster = MarkerCluster(
    name="ATM Locations",
    options={
        "maxClusterRadius": 50,
        "disableClusteringAtZoom": 13
    }
).add_to(m)

for _, row in gdf.iterrows():

    popup_html = f"""
    <div style="font-family: Arial; width: 260px;">

        <h4 style="margin-bottom:8px;">
            ATM Information
        </h4>

        <b>Bank:</b> {row['bank_name']}<br>
        <b>ATM ID:</b> {row['atm_cd']}<br>
        <b>District:</b> {row['dtname']}<br>
        <b>City:</b> {row['atm_city'] or 'N/A'}<br>
        <b>PIN:</b> {row['atm_pin_cd'] or 'N/A'}<br>

        <hr>

        <b>Latitude:</b> {row['atm_lat']:.6f}<br>
        <b>Longitude:</b> {row['atm_long']:.6f}

    </div>
    """

    folium.CircleMarker(
        location=[
            row["atm_lat"],
            row["atm_long"]
        ],
        radius=4,
        popup=folium.Popup(
            popup_html,
            max_width=300
        ),
        tooltip=row["bank_name"],
        fill=True,
        fill_opacity=0.8,
        weight=1
    ).add_to(cluster)

folium.LayerControl().add_to(m)

display(m)

# ============================================================
# STEP 8: ATM DENSITY HEATMAP
# ============================================================

heatmap_map = folium.Map(
    location=[17.9, 79.5],
    zoom_start=7,
    tiles="OpenStreetMap"
)

heat_data = [
    [lat, lon]
    for lat, lon in zip(
        gdf["atm_lat"],
        gdf["atm_long"]
    )
]

HeatMap(
    heat_data,
    radius=18,
    blur=22,
    min_opacity=0.25,
    max_zoom=12
).add_to(heatmap_map)

display(heatmap_map)

