import pandas as pd
import numpy as np
import geopandas as gpd
import folium

from folium.plugins import HeatMap, MarkerCluster
from IPython.display import display

CSV_FILE = "/content/telangana_nic_atm_9642.csv"

df = pd.read_csv(CSV_FILE)

print("Original dataset:")
print(f"Rows    : {len(df):,}")
print(f"Columns : {len(df.columns)}")

# ------------------------------------------------------------
# Standardize column names
# ------------------------------------------------------------

df.columns = (
    df.columns
    .str.strip()
    .str.lower()
)

# ------------------------------------------------------------
# Clean text fields
# ------------------------------------------------------------

text_cols = [
    "bank_name",
    "atm_cd",
    "stname",
    "dtname",
    "atm_city",
    "atm_pin_cd"
]

for col in text_cols:
    if col in df.columns:
        df[col] = (
            df[col]
            .fillna("")
            .astype(str)
            .str.strip()
        )

# ------------------------------------------------------------
# Coordinates
# ------------------------------------------------------------

df["atm_lat"] = pd.to_numeric(
    df["atm_lat"],
    errors="coerce"
)

df["atm_long"] = pd.to_numeric(
    df["atm_long"],
    errors="coerce"
)

# ------------------------------------------------------------
# Coordinate validity
# ------------------------------------------------------------

valid = (
    df["atm_lat"].between(15.5, 20.5)
    &
    df["atm_long"].between(77.0, 82.0)
)

df["coordinate_valid"] = valid

# ------------------------------------------------------------
# Duplicate ATM ID flag
# DO NOT DELETE THEM YET
# ------------------------------------------------------------

df["duplicate_atm_id"] = (
    df["atm_cd"]
    .ne("")
    &
    df["atm_cd"].duplicated(keep=False)
)

# ------------------------------------------------------------
# Duplicate coordinate flag
# ------------------------------------------------------------

coordinate_counts = (
    df.groupby(
        ["atm_lat", "atm_long"],
        dropna=False
    )["atm_cd"]
    .transform("count")
)

df["same_coordinate_count"] = coordinate_counts

df["shared_coordinate"] = (
    df["same_coordinate_count"] > 1
)

# ------------------------------------------------------------
# Keep only valid GIS coordinates
# ------------------------------------------------------------

gis_df = df[
    df["coordinate_valid"]
].copy()

print("\nGIS dataset:")
print(f"Valid ATM locations : {len(gis_df):,}")
print(
    f"Invalid coordinates : "
    f"{len(df) - len(gis_df):,}"
)

print(
    f"Duplicate ATM IDs   : "
    f"{gis_df['duplicate_atm_id'].sum():,} records"
)

print(
    f"Shared coordinates  : "
    f"{gis_df['shared_coordinate'].sum():,} records"
)

display(gis_df.head())

# ============================================================
# STEP 10 — GeoDataFrame
# ============================================================

gdf = gpd.GeoDataFrame(
    gis_df,
    geometry=gpd.points_from_xy(
        gis_df["atm_long"],
        gis_df["atm_lat"]
    ),
    crs="EPSG:4326"
)

print(gdf.crs)
print(f"GIS features: {len(gdf):,}")

# ============================================================
# STEP 11 — Predictive Intelligence Schema
# ============================================================

gdf["risk_score"] = np.nan

gdf["risk_level"] = "UNASSESSED"

gdf["prediction_window"] = None

gdf["predicted_withdrawal_probability"] = np.nan

gdf["historical_withdrawals"] = np.nan

gdf["suspicious_withdrawals"] = np.nan

gdf["risk_factors"] = None

gdf["model_confidence"] = np.nan

print("Predictive schema created.")

display(
    gdf[
        [
            "atm_cd",
            "bank_name",
            "dtname",
            "atm_city",
            "risk_score",
            "risk_level",
            "prediction_window"
        ]
    ].head()
)

# ============================================================
# STEP 12 — Intelligence Card
# ============================================================

def create_atm_card(row):

    bank = row["bank_name"] or "Unknown Bank"
    atm_id = row["atm_cd"] or "N/A"
    district = row["dtname"] or "Unknown District"
    city = row["atm_city"] or "Unknown City"
    pin = row["atm_pin_cd"] or "N/A"

    lat = row["atm_lat"]
    lon = row["atm_long"]

    duplicate_warning = ""

    if row["duplicate_atm_id"]:
        duplicate_warning = """
        <div style="
            margin-top:10px;
            padding:8px;
            border-radius:6px;
            background:#3b2f12;
            color:#f5c542;
            font-size:11px;">
            ⚠ Duplicate ATM ID in source dataset
        </div>
        """

    shared_location = ""

    if row["shared_coordinate"]:
        shared_location = f"""
        <div style="
            margin-top:6px;
            font-size:11px;
            color:#9ca3af;">
            {int(row["same_coordinate_count"])}
            records share this coordinate
        </div>
        """

    html = f"""
    <div style="
        width:320px;
        font-family:Inter,Arial,sans-serif;
        color:#e5e7eb;
        background:#111827;
        border-radius:14px;
        overflow:hidden;
    ">

        <!-- HEADER -->

        <div style="
            padding:16px;
            background:linear-gradient(
                135deg,
                #111827,
                #1f2937
            );
            border-bottom:1px solid #374151;
        ">

            <div style="
                font-size:11px;
                color:#9ca3af;
                text-transform:uppercase;
                letter-spacing:1px;
            ">
                ATM INFRASTRUCTURE
            </div>

            <div style="
                margin-top:5px;
                font-size:20px;
                font-weight:700;
            ">
                {bank}
            </div>

            <div style="
                margin-top:4px;
                font-size:12px;
                color:#9ca3af;
            ">
                ATM ID • {atm_id}
            </div>

        </div>


        <!-- LOCATION -->

        <div style="padding:14px 16px;">

            <div style="
                font-size:12px;
                color:#9ca3af;
                margin-bottom:5px;
            ">
                LOCATION
            </div>

            <div style="
                font-size:14px;
                font-weight:600;
            ">
                {city}
            </div>

            <div style="
                margin-top:3px;
                font-size:12px;
                color:#9ca3af;
            ">
                {district}
            </div>

            <div style="
                margin-top:8px;
                font-size:11px;
                color:#6b7280;
            ">
                {lat:.6f}, {lon:.6f}
            </div>

            {shared_location}
            {duplicate_warning}

        </div>


        <!-- CURRENT INTELLIGENCE -->

        <div style="
            margin:0 16px 16px 16px;
            padding:14px;
            border-radius:10px;
            background:#1f2937;
            border:1px solid #374151;
        ">

            <div style="
                font-size:10px;
                color:#9ca3af;
                text-transform:uppercase;
                letter-spacing:1px;
            ">
                PREDICTIVE RISK
            </div>

            <div style="
                margin-top:8px;
                font-size:18px;
                font-weight:700;
                color:#6b7280;
            ">
                UNASSESSED
            </div>

            <div style="
                margin-top:4px;
                font-size:11px;
                color:#9ca3af;
            ">
                Awaiting predictive model output
            </div>

        </div>


        <!-- FOOTER -->

        <div style="
            padding:10px 16px;
            background:#0b1220;
            font-size:10px;
            color:#6b7280;
        ">
            NIC ATM Infrastructure Layer
        </div>

    </div>
    """

    return html

# ============================================================
# STEP 13 — Interactive Telangana GIS
# ============================================================

m = folium.Map(
    location=[17.95, 79.50],
    zoom_start=7,
    tiles=None,
    control_scale=True
)

# ------------------------------------------------------------
# Dark basemap
# ------------------------------------------------------------

folium.TileLayer(
    tiles="CartoDB dark_matter",
    name="Dark",
    control=True
).add_to(m)

# ------------------------------------------------------------
# Light basemap
# ------------------------------------------------------------

folium.TileLayer(
    tiles="CartoDB positron",
    name="Light",
    control=True
).add_to(m)

# ------------------------------------------------------------
# ATM cluster layer
# ------------------------------------------------------------

atm_cluster = MarkerCluster(
    name="ATM Infrastructure",
    options={
        "maxClusterRadius": 45,
        "disableClusteringAtZoom": 13,
        "spiderfyOnMaxZoom": True
    }
)

atm_cluster.add_to(m)


# ------------------------------------------------------------
# Add ATM points
# ------------------------------------------------------------

for _, row in gdf.iterrows():

    popup = folium.Popup(
        create_atm_card(row),
        max_width=360
    )

    folium.CircleMarker(
        location=[
            row["atm_lat"],
            row["atm_long"]
        ],

        radius=4,

        color="#60a5fa",

        weight=1,

        fill=True,

        fill_color="#3b82f6",

        fill_opacity=0.85,

        popup=popup,

        tooltip=f"""
        {row['bank_name']}
        • {row['atm_cd']}
        """
    ).add_to(atm_cluster)


# ------------------------------------------------------------
# Heatmap layer
# ------------------------------------------------------------

heat_layer = folium.FeatureGroup(
    name="ATM Density",
    show=False
)

heat_data = [
    [
        row["atm_lat"],
        row["atm_long"],
        1
    ]
    for _, row in gdf.iterrows()
]

HeatMap(
    heat_data,
    radius=22,
    blur=25,
    min_opacity=0.25,
    max_zoom=11
).add_to(heat_layer)

heat_layer.add_to(m)


# ------------------------------------------------------------
# Layer controls
# ------------------------------------------------------------

folium.LayerControl(
    collapsed=False
).add_to(m)


display(m)

