# ================================================================
# 33. CREATE RISK GEOJSON
# ================================================================

risk_geojson = None


if (
    telangana is not None
    and gis_district_col is not None
):

    try:

        risk_geojson = json.loads(
            telangana.to_json()
        )


        # Create lookup

        risk_lookup = {}

        for _, row in district_risk.iterrows():

            key = clean_district_name(
                row["District"]
            )

            risk_lookup[key] = row


        # Add analysis values to GIS

        for feature in risk_geojson["features"]:

            properties = feature.get(
                "properties",
                {}
            )


            gis_name = properties.get(
                gis_district_col,
                ""
            )


            normalized_name = (
                clean_district_name(
                    gis_name
                )
            )


            result = risk_lookup.get(
                normalized_name
            )


            if result is not None:

                properties["Risk_Score"] = float(
                    result["Risk_Score"]
                )

                properties["Risk_Level"] = (
                    result["Risk_Level"]
                )

                properties["ATM_Count"] = int(
                    result["ATM_Count"]
                )

                properties["Fraud_Count"] = int(
                    result["Fraud_Count"]
                )

                properties["Transaction_Count"] = int(
                    result["Transaction_Count"]
                )

            else:

                properties["Risk_Score"] = 0
                properties["Risk_Level"] = "LOW"
                properties["ATM_Count"] = 0
                properties["Fraud_Count"] = 0
                properties["Transaction_Count"] = 0


            feature["properties"] = properties


    except Exception as e:

        print()
        print(
            "Risk GIS preparation failed."
        )

        risk_geojson = None


