# ================================================================
# 16. SAFE TELANGANA UNION
# ================================================================
#
# We never perform unary_union on the raw geometry.
# All geometries are repaired first.
#
# Several fallback methods are used.
# ================================================================

telangana_union = None


if telangana is not None:

    safe_geometries = []

    for geom in telangana.geometry:

        try:

            if geom is None:
                continue

            if geom.is_empty:
                continue

            fixed = make_valid(geom)

            if fixed is None:
                continue

            if not fixed.is_valid:

                fixed = fixed.buffer(0)

            if fixed is not None and not fixed.is_empty:

                safe_geometries.append(
                    fixed
                )

        except Exception:
            pass


    # ------------------------------------------------------------
    # Method 1: unary_union
    # ------------------------------------------------------------

    if len(safe_geometries) > 0:

        try:

            telangana_union = unary_union(
                safe_geometries
            )

        except Exception:

            telangana_union = None


    # ------------------------------------------------------------
    # Method 2: union one-by-one
    # ------------------------------------------------------------

    if telangana_union is None:

        try:

            current = safe_geometries[0]

            for geom in safe_geometries[1:]:

                try:

                    current = current.union(
                        geom
                    )

                except Exception:

                    try:

                        current = current.union(
                            geom.buffer(0)
                        )

                    except Exception:
                        pass

            telangana_union = current

        except Exception:

            telangana_union = None


    # ------------------------------------------------------------
    # Method 3: convex hull
    # ------------------------------------------------------------

    if telangana_union is None:

        try:

            hulls = [
                g.convex_hull
                for g in safe_geometries
            ]

            telangana_union = unary_union(
                hulls
            )

        except Exception:

            telangana_union = None


