# ================================================================
# 18. NORMALIZE DISTRICT NAMES
# ================================================================

def clean_district_name(value):

    if pd.isna(value):

        return "unknown"


    text = str(value).strip()


    # Replace separators

    text = text.replace(
        "_",
        " "
    )

    text = text.replace(
        "-",
        " "
    )


    # Remove word "district" safely
    # No invalid case argument.

    text = re.sub(
        r"\bdistrict\b",
        "",
        text,
        flags=re.IGNORECASE
    )


    # Remove extra spaces

    text = " ".join(
        text.split()
    )


    return text.lower().strip()


