# ================================================================
# 22. GENERATE DEMO FRAUD DATA
# ================================================================

# Base synthetic risk

atm_join["Base_Risk"] = rng.uniform(
    0.05,
    0.85,
    len(atm_join)
)


# Fraud probability

fraud_probability = (
    0.003
    +
    atm_join["Base_Risk"] * 0.012
)


# Fraud count

fraud_counts = []

for transactions, probability in zip(
    atm_join["Transactions"],
    fraud_probability
):

    fraud_count = rng.binomial(
        int(transactions),
        float(probability)
    )

    fraud_counts.append(
        fraud_count
    )


atm_join["Fraud_Count"] = (
    fraud_counts
)


# ================================================================
# 23. ATM FRAUD RATE
# ================================================================

atm_join["Fraud_Rate"] = np.where(

    atm_join["Transactions"] > 0,

    atm_join["Fraud_Count"]
    /
    atm_join["Transactions"],

    0
)


# ================================================================
# 24. NORMALIZATION FUNCTION
# ================================================================

def minmax(series):

    values = pd.to_numeric(
        series,
        errors="coerce"
    ).fillna(0).astype(float)


    minimum = values.min()
    maximum = values.max()


    if maximum == minimum:

        return pd.Series(
            np.zeros(
                len(values)
            ),
            index=values.index
        )


    return (
        (values - minimum)
        /
        (maximum - minimum)
    )


