print("Latitude     :", lat_col)
print("Longitude    :", lon_col)
print("District     :", district_col)


# ================================================================
# 9. GUARANTEE REQUIRED COLUMNS
# ================================================================

rng = np.random.default_rng(42)


if atm_id_col is None:

    demo["atm_id"] = [
        f"DEMO_ATM_{i+1:04d}"
        for i in range(len(demo))
    ]

    atm_id_col = "atm_id"


if bank_col is None:

    demo["bank_name"] = rng.choice(
        [
            "SBI",
            "HDFC Bank",
            "ICICI Bank",
            "Axis Bank"
        ],
        len(demo)
    )

    bank_col = "bank_name"


if lat_col is None:

    demo["atm_lat"] = rng.uniform(
        16.05,
        19.45,
        len(demo)
    )

    lat_col = "atm_lat"


if lon_col is None:

    demo["atm_long"] = rng.uniform(
        77.20,
        81.25,
        len(demo)
    )

    lon_col = "atm_long"


if district_col is None:

    demo["dtname"] = "Unknown"

    district_col = "dtname"


# ================================================================
# 10. CLEAN COORDINATES
# ================================================================

demo[lat_col] = pd.to_numeric(
    demo[lat_col],
    errors="coerce"
)

demo[lon_col] = pd.to_numeric(
    demo[lon_col],
    errors="coerce"
)

demo = demo.dropna(
    subset=[
        lat_col,
        lon_col
    ]
).copy()


# ================================================================
# 11. REMOVE IMPOSSIBLE COORDINATES
# ================================================================

demo = demo[
    (demo[lat_col] >= 15.0) &
    (demo[lat_col] <= 20.5) &
    (demo[lon_col] >= 76.0) &
    (demo[lon_col] <= 82.5)
].copy()


print()
print("=" * 80)
print("ATM DEMO DATA")
print("=" * 80)

print()
print("ATM source records:", len(demo))


# ================================================================
# 12. CREATE ATM GEODATAFRAME
# ================================================================

atm = gpd.GeoDataFrame(
    demo.copy(),

    geometry=[
        Point(
            float(lon),
            float(lat)
        )
        for lat, lon in zip(
            demo[lat_col],
            demo[lon_col]
        )
    ],

    crs="EPSG:4326"
)


# ================================================================
# 13. LOAD TELANGANA GIS
# ================================================================

print()
print("=" * 80)
print("LOADING TELANGANA DISTRICT GIS")
print("=" * 80)


telangana = None


try:

    response = requests.get(
        GIS_URL,
        timeout=40
    )

    response.raise_for_status()

    gis_json = response.json()

    if (
        isinstance(gis_json, dict)
        and "features" in gis_json
    ):

        telangana = gpd.GeoDataFrame.from_features(
            gis_json["features"],
            crs="EPSG:4326"
        )

        print()
        print("Telangana GIS downloaded successfully.")

    else:

        raise ValueError(
            "Invalid GeoJSON structure"
        )


except Exception as e:

    print()
    print(
        "GIS download failed."
    )

    print(
        "Using built-in fallback boundary."
    )


# ================================================================
# 14. REPAIR GIS GEOMETRIES
# ================================================================

if telangana is not None:

    print()
    print("Repairing district geometries...")

    repaired_geometries = []

    for geom in telangana.geometry:

        try:

            if geom is None or geom.is_empty:

                repaired_geometries.append(None)
                continue


            # First repair
            fixed = make_valid(geom)


            # Second repair
            if fixed is not None and not fixed.is_valid:

                fixed = fixed.buffer(0)


            # Third repair
            if fixed is not None and not fixed.is_valid:

                fixed = fixed.buffer(0)


            repaired_geometries.append(
                fixed
            )

        except Exception:

            try:

                fixed = geom.buffer(0)

                repaired_geometries.append(
                    fixed
                )

            except Exception:

                repaired_geometries.append(
                    None
                )


    telangana["geometry"] = repaired_geometries


    # Remove empty/null geometries

    telangana = telangana[
        telangana.geometry.notna()
    ].copy()

    telangana = telangana[
        ~telangana.geometry.is_empty
    ].copy()


    # Final geometry repair

    final_geometries = []

    for geom in telangana.geometry:

        try:

            if geom.is_valid:

                final_geometries.append(
                    geom
                )

            else:

                final_geometries.append(
                    geom.buffer(0)
                )

        except Exception:

            final_geometries.append(
                None
            )


    telangana["geometry"] = final_geometries

    telangana = telangana[
        telangana.geometry.notna()
    ].copy()

    telangana = telangana[
        ~telangana.geometry.is_empty
    ].copy()


    print(
        "District polygons:",
        len(telangana)
    )


# ================================================================
# 15. DETECT GIS DISTRICT COLUMN
# ================================================================

gis_district_col = None


if telangana is not None:

    gis_district_col = find_column(
        telangana,
        [
            "district",
            "district_name",
            "districtname",
            "dtname",
            "DISTRICT_N",
            "NAME_2",
            "name_2"
        ]
    )


    # If not found, search object columns

    if gis_district_col is None:

        for c in telangana.columns:

            if c == "geometry":
                continue

            if telangana[c].dtype == "object":

                gis_district_col = c
                break


print(
    "GIS district column:",
    gis_district_col
)


# ================================================================
# 16. SAFE TELANGANA UNION
# ================================================================
#
# We never perform unary_union on the raw geometry.
# All geometries are repaired first.
#
# Several fallback methods are used.
# ================================================================

telangana_union = None


if telangana is not None:

    safe_geometries = []

    for geom in telangana.geometry:

        try:

            if geom is None:
                continue

            if geom.is_empty:
                continue

            fixed = make_valid(geom)

            if fixed is None:
                continue

            if not fixed.is_valid:

                fixed = fixed.buffer(0)

            if fixed is not None and not fixed.is_empty:

                safe_geometries.append(
                    fixed
                )

        except Exception:
            pass


    # ------------------------------------------------------------
    # Method 1: unary_union
    # ------------------------------------------------------------

    if len(safe_geometries) > 0:

        try:

            telangana_union = unary_union(
                safe_geometries
            )

        except Exception:

            telangana_union = None


    # ------------------------------------------------------------
    # Method 2: union one-by-one
    # ------------------------------------------------------------

    if telangana_union is None:

        try:

            current = safe_geometries[0]

            for geom in safe_geometries[1:]:

                try:

                    current = current.union(
                        geom
                    )

                except Exception:

                    try:

                        current = current.union(
                            geom.buffer(0)
                        )

                    except Exception:
                        pass

            telangana_union = current

        except Exception:

            telangana_union = None


    # ------------------------------------------------------------
    # Method 3: convex hull
    # ------------------------------------------------------------

    if telangana_union is None:

        try:

            hulls = [
                g.convex_hull
                for g in safe_geometries
            ]

            telangana_union = unary_union(
                hulls
            )

        except Exception:

            telangana_union = None


# ================================================================
# 17. BUILT-IN FALLBACK TELANGANA OUTLINE
# ================================================================

if telangana_union is None:

    print()
    print(
        "Using built-in Telangana boundary."
    )


    fallback_coords = [

        (77.20, 19.00),

        (77.90, 19.45),

        (78.80, 19.75),

        (79.80, 19.70),

        (80.65, 19.25),

        (81.25, 18.60),

        (81.35, 17.70),

        (81.00, 16.90),

        (80.40, 16.25),

        (79.50, 15.85),

        (78.60, 15.95),

        (77.65, 16.15),

        (77.00, 16.90),

        (76.75, 17.75),

        (76.95, 18.55),

        (77.20, 19.00)
    ]


    telangana_union = Polygon(
        fallback_coords
    )


# ================================================================
# 18. KEEP EXACTLY 30 ATMs INSIDE TELANGANA
# ================================================================

print()
print("=" * 80)
print("SELECTING EXACTLY 30 ATM POINTS INSIDE TELANGANA")
print("=" * 80)

# Keep only ATM points physically inside the Telangana state boundary.
# This is done using the repaired Telangana geometry, not just the
# latitude/longitude bounding box.

inside_mask = atm.geometry.apply(
    lambda geom: (
        geom is not None
        and not geom.is_empty
        and telangana_union.covers(geom)
    )
)

atm = atm.loc[inside_mask].copy()

print("ATMs inside Telangana before selection:", len(atm))

rng = np.random.default_rng(42)

# If there are more than 30 valid points, select exactly 30.
if len(atm) > MAX_ATMS:
    atm = atm.sample(
        n=MAX_ATMS,
        random_state=42
    ).copy()

# If the source file has fewer than 30 valid points inside Telangana,
# generate additional DEMO points inside the actual Telangana polygon.
if len(atm) < MAX_ATMS:

    points_needed = MAX_ATMS - len(atm)

    minx, miny, maxx, maxy = telangana_union.bounds

    generated_rows = []

    attempts = 0
    max_attempts = 20000

    while (
        len(generated_rows) < points_needed
        and attempts < max_attempts
    ):

        attempts += 1

        x = rng.uniform(minx, maxx)
        y = rng.uniform(miny, maxy)

        point = Point(x, y)

        if not telangana_union.covers(point):
            continue

        # Use an existing ATM row as a template so all original
        # columns remain available.
        if len(atm) > 0:
            template = atm.iloc[
                len(generated_rows) % len(atm)
            ].copy()
        else:
            template = demo.iloc[
                len(generated_rows) % len(demo)
            ].copy()

        template[lat_col] = y
        template[lon_col] = x
        template[atm_id_col] = (
            f"DEMO_ATM_EXTRA_{len(generated_rows)+1:03d}"
        )

        template["geometry"] = point

        generated_rows.append(template)

    if generated_rows:

        generated_gdf = gpd.GeoDataFrame(
            generated_rows,
            geometry="geometry",
            crs="EPSG:4326"
        )

        atm = gpd.GeoDataFrame(
            pd.concat(
                [atm, generated_gdf],
                ignore_index=True
            ),
            geometry="geometry",
            crs="EPSG:4326"
        )

# Final safety check.
atm = atm.loc[
    atm.geometry.apply(
        lambda geom: (
            geom is not None
            and not geom.is_empty
            and telangana_union.covers(geom)
        )
    )
].copy()

# If a pathological GIS/source issue prevents 30 points, stop rather
# than silently displaying an incorrect number.
if len(atm) != MAX_ATMS:
    raise RuntimeError(
        f"Could not create exactly {MAX_ATMS} ATM points "
        f"inside the Telangana boundary. "
        f"Valid points available: {len(atm)}"
    )

print("FINAL ATM POINTS:", len(atm))
print("All 30 points are inside the Telangana boundary.")


# ================================================================
# 19. NORMALIZE DISTRICT NAMES
# ================================================================

def clean_district_name(value):

    if pd.isna(value):

        return "unknown"


    text = str(value).strip()


    # Replace separators

    text = text.replace(
        "_",
        " "
    )

    text = text.replace(
        "-",
        " "
    )


    # Remove word "district" safely
    # No invalid case argument.

    text = re.sub(
        r"\bdistrict\b",
        "",
        text,
        flags=re.IGNORECASE
    )


    # Remove extra spaces

    text = " ".join(
        text.split()
    )


    return text.lower().strip()


# ================================================================
# 19. SPATIAL JOIN
# ================================================================

print()
print("=" * 80)
print("ASSIGNING ATM POINTS TO DISTRICTS")
print("=" * 80)


if (
    telangana is not None
    and gis_district_col is not None
):

    try:

        gis_for_join = telangana[
            [
                gis_district_col,
                "geometry"
            ]
        ].copy()


        atm_join = gpd.sjoin(
            atm,
            gis_for_join,
            how="left",
            predicate="within"
        )


        atm_join = atm_join.drop(
            columns=[
                "index_right"
            ],
            errors="ignore"
        )


        atm_join["GIS_District"] = (
            atm_join[
                gis_district_col
            ]
        )


        print(
            "Spatial join completed."
        )


    except Exception as e:

        print(
            "Spatial join failed."
        )

        print(
            "Using demo district names."
        )

        atm_join = atm.copy()

        atm_join["GIS_District"] = (
            atm_join[district_col]
        )

else:

    atm_join = atm.copy()

    atm_join["GIS_District"] = (
        atm_join[district_col]
    )


# ================================================================
# 20. DISTRICT NAME ASSIGNMENT
# ================================================================

atm_join["GIS_District_Clean"] = (
    atm_join["GIS_District"]
    .apply(clean_district_name)
)


atm_join["Demo_District_Clean"] = (
    atm_join[district_col]
    .apply(clean_district_name)
)


# Use GIS district where available,
# otherwise use demo CSV district.

atm_join["District"] = (
    atm_join["GIS_District_Clean"]
    .replace(
        [
            "",
            "unknown",
            "nan",
            "none"
        ],
        np.nan
    )
)


atm_join["District"] = (
    atm_join["District"]
    .fillna(
        atm_join["Demo_District_Clean"]
    )
)


# Display-friendly name

atm_join["District"] = (
    atm_join["District"]
    .astype(str)
    .str.strip()
    .str.title()
)


print()
print(
    "District assignment completed."
)

print(
    "Districts represented in ATM data:",
    atm_join["District"].nunique()
)


# ================================================================
# 21. GENERATE DEMO TRANSACTIONS
# ================================================================
#
# These are synthetic values.
# They do NOT come from the transaction CSV files.
# ================================================================

rng = np.random.default_rng(42)


# Transaction volume

atm_join["Transactions"] = (
    rng.poisson(
        lam=500,
        size=len(atm_join)
    )
    + 100
)


# Average transaction amount

average_amount = rng.uniform(
    700,
    3000,
    len(atm_join)
)


atm_join["Transaction_Amount"] = (
    atm_join["Transactions"]
    * average_amount
).round(2)


# ================================================================
# 22. GENERATE DEMO FRAUD DATA
# ================================================================

# Base synthetic risk

atm_join["Base_Risk"] = rng.uniform(
    0.05,
    0.85,
    len(atm_join)
)


# Fraud probability

fraud_probability = (
    0.003
    +
    atm_join["Base_Risk"] * 0.012
)


# Fraud count

fraud_counts = []

for transactions, probability in zip(
    atm_join["Transactions"],
    fraud_probability
):

    fraud_count = rng.binomial(
        int(transactions),
        float(probability)
    )

    fraud_counts.append(
        fraud_count
    )


atm_join["Fraud_Count"] = (
    fraud_counts
)


# ================================================================
# 23. ATM FRAUD RATE
# ================================================================

atm_join["Fraud_Rate"] = np.where(

    atm_join["Transactions"] > 0,

    atm_join["Fraud_Count"]
    /
    atm_join["Transactions"],

    0
)


# ================================================================
# 24. NORMALIZATION FUNCTION
# ================================================================

def minmax(series):

    values = pd.to_numeric(
        series,
        errors="coerce"
    ).fillna(0).astype(float)


    minimum = values.min()
    maximum = values.max()


    if maximum == minimum:

        return pd.Series(
            np.zeros(
                len(values)
            ),
            index=values.index
        )


    return (
        (values - minimum)
        /
        (maximum - minimum)
    )


# ================================================================
# 25. DISTRICT LEVEL ANALYSIS
# ================================================================

district_risk = (

    atm_join

    .groupby(
        "District",
        dropna=False
    )

    .agg(

        ATM_Count=(
            "District",
            "size"
        ),

        Bank_Count=(
            bank_col,
            "nunique"
        ),

        Transaction_Count=(
            "Transactions",
            "sum"
        ),

        Transaction_Amount=(
            "Transaction_Amount",
            "sum"
        ),

        Fraud_Count=(
            "Fraud_Count",
            "sum"
        )

    )

    .reset_index()
)


# ================================================================
# 26. DISTRICT FRAUD RATE
# ================================================================

district_risk["Fraud_Rate"] = np.where(

    district_risk["Transaction_Count"] > 0,

    district_risk["Fraud_Count"]
    /
    district_risk["Transaction_Count"],

    0
)


# ================================================================
# 27. RISK COMPONENTS
# ================================================================

district_risk["ATM_Score"] = minmax(
    district_risk["ATM_Count"]
)


district_risk["Fraud_Score"] = minmax(
    district_risk["Fraud_Count"]
)


district_risk["Fraud_Rate_Score"] = minmax(
    district_risk["Fraud_Rate"]
)


district_risk["Activity_Score"] = minmax(
    district_risk["Transaction_Count"]
)


# ================================================================
# 28. DISTRICT RISK SCORE
# ================================================================

district_risk["Risk_Score"] = (

    0.30
    *
    district_risk["ATM_Score"]

    +

    0.35
    *
    district_risk["Fraud_Score"]

    +

    0.20
    *
    district_risk["Fraud_Rate_Score"]

    +

    0.15
    *
    district_risk["Activity_Score"]

) * 100


district_risk["Risk_Score"] = (
    district_risk["Risk_Score"]
    .clip(0, 100)
    .round(2)
)


# ================================================================
# 29. RISK LEVEL
# ================================================================

def risk_level(score):

    score = float(score)

    if score >= 66:

        return "HIGH"

    elif score >= 33:

        return "MEDIUM"

    else:

        return "LOW"


district_risk["Risk_Level"] = (
    district_risk["Risk_Score"]
    .apply(risk_level)
)


# ================================================================
# 30. MERGE DISTRICT RISK TO ATM DATA
# ================================================================

atm_join = atm_join.merge(

    district_risk[
        [
            "District",
            "Risk_Score",
            "Risk_Level"
        ]
    ],

    on="District",

    how="left"
)


# ================================================================
# 31. ATM LEVEL RISK
# ================================================================

atm_fraud_component = minmax(
    atm_join["Fraud_Count"]
)


atm_activity_component = minmax(
    atm_join["Transactions"]
)


atm_join["ATM_Risk_Score"] = (

    0.65
    *
    atm_join["Risk_Score"]

    +

    0.20
    *
    atm_fraud_component
    *
    100

    +

    0.15
    *
    atm_activity_component
    *
    100

)


atm_join["ATM_Risk_Score"] = (

    atm_join["ATM_Risk_Score"]
    .clip(0, 100)
    .round(2)

)


atm_join["ATM_Risk_Level"] = (
    atm_join["ATM_Risk_Score"]
    .apply(risk_level)
)


# ================================================================
# 32. PRINT SUMMARY
# ================================================================

total_atms = len(atm_join)

total_banks = atm_join[
    bank_col
].nunique()

total_transactions = int(
    district_risk[
        "Transaction_Count"
    ].sum()
)

total_frauds = int(
    district_risk[
        "Fraud_Count"
    ].sum()
)

total_amount = float(
    district_risk[
        "Transaction_Amount"
    ].sum()
)


print()
print("=" * 80)
print("DEMO RISK ANALYSIS")
print("=" * 80)

print()
print(
    "Total ATM Locations :",
    f"{total_atms:,}"
)

print(
    "Districts           :",
    f"{district_risk['District'].nunique():,}"
)

print(
    "Banks               :",
    f"{total_banks:,}"
)

print(
    "Transactions        :",
    f"{total_transactions:,}"
)

print(
    "Fraud Cases         :",
    f"{total_frauds:,}"
)

print(
    "Transaction Amount  :",
    f"₹{total_amount:,.0f}"
)


# ================================================================
# 33. CREATE RISK GEOJSON
# ================================================================

risk_geojson = None


if (
    telangana is not None
    and gis_district_col is not None
):

    try:

        risk_geojson = json.loads(
            telangana.to_json()
        )


        # Create lookup

        risk_lookup = {}

        for _, row in district_risk.iterrows():

            key = clean_district_name(
                row["District"]
            )

            risk_lookup[key] = row


        # Add analysis values to GIS

        for feature in risk_geojson["features"]:

            properties = feature.get(
                "properties",
                {}
            )


            gis_name = properties.get(
                gis_district_col,
                ""
            )


            normalized_name = (
                clean_district_name(
                    gis_name
                )
            )


            result = risk_lookup.get(
                normalized_name
            )


            if result is not None:

                properties["Risk_Score"] = float(
                    result["Risk_Score"]
                )

                properties["Risk_Level"] = (
                    result["Risk_Level"]
                )

                properties["ATM_Count"] = int(
                    result["ATM_Count"]
                )

                properties["Fraud_Count"] = int(
                    result["Fraud_Count"]
                )

                properties["Transaction_Count"] = int(
                    result["Transaction_Count"]
                )

            else:

                properties["Risk_Score"] = 0
                properties["Risk_Level"] = "LOW"
                properties["ATM_Count"] = 0
                properties["Fraud_Count"] = 0
                properties["Transaction_Count"] = 0


            feature["properties"] = properties


    except Exception as e:

        print()
        print(
            "Risk GIS preparation failed."
        )

        risk_geojson = None


