    removeLayer(districtLayer);

    removeLayer(riskLayer);

    removeLayer(atmLayer);

    removeLayer(densityLayer);

    removeLayer(fraudLayer);

    removeLayer(highRiskLayer);

    removeLayer(labelLayer);


