# 25. THREE CRIME RISK LEVELS
# ================================================================

def crime_level(count):

    count = int(count)


    if count >= 5000:

        return "HIGH"


    elif count >= 2500:

        return "MEDIUM"


    else:

        return "LOW"


telangana["Crime_Risk_Level"] = (

    telangana[
        "Crime_Reports"
    ]

    .apply(
        crime_level
    )

)


