print("LOADING TELANGANA DISTRICT GIS")
print("=" * 80)


telangana = None


try:

    response = requests.get(

        GIS_URL,

        timeout=40

    )


    response.raise_for_status()


    gis_json = response.json()


    if (

        isinstance(gis_json, dict)

        and "features" in gis_json

    ):

        telangana = (

            gpd.GeoDataFrame.from_features(

                gis_json["features"],

                crs="EPSG:4326"

            )

        )


        print()
        print(
            "Telangana GIS downloaded successfully."
        )


    else:

        raise ValueError(
            "Invalid GeoJSON structure."
        )


except Exception as e:

    print()
    print(
        "GIS download failed."
    )

    print(
        "Reason:",
        e
    )

    print()
    print(
        "Using fallback Telangana boundary."
    )


# ================================================================
# 13. REPAIR GIS GEOMETRIES
# ================================================================

if telangana is not None:

    repaired = []


    for geom in telangana.geometry:

        try:

            if (
                geom is None
                or geom.is_empty
            ):

                repaired.append(None)

                continue


            fixed = make_valid(
                geom
            )


            if (
                fixed is not None
                and not fixed.is_valid
            ):

                fixed = fixed.buffer(0)


            repaired.append(
                fixed
            )


        except Exception:

            try:

                repaired.append(
                    geom.buffer(0)
                )

            except Exception:

                repaired.append(None)


    telangana["geometry"] = repaired


    telangana = telangana[
        telangana.geometry.notna()
    ].copy()


    telangana = telangana[
        ~telangana.geometry.is_empty
    ].copy()


    print(
        "District polygons:",
        len(telangana)
    )


