print("=" * 80)


try:

    gis_join = telangana[

        [
            gis_district_col,
            "geometry"
        ]

    ].copy()


    atm_join = gpd.sjoin(

        atm,

        gis_join,

        how="left",

        predicate="within"

    )


    atm_join = atm_join.drop(

        columns=[
            "index_right"
        ],

        errors="ignore"

    )


    atm_join["District"] = (

        atm_join[
            gis_district_col
        ]

        .fillna(
            atm_join[district_col]
        )

        .astype(str)

        .str.strip()

        .str.title()

    )


except Exception as e:

    print(
        "Spatial join failed."
    )

    print(e)


    atm_join = atm.copy()


    atm_join["District"] = (

        atm_join[
            district_col
        ]

        .astype(str)

        .str.strip()

        .str.title()

    )


print(
    "District assignment completed."
)


# ================================================================
# 18. SAME DEMO TRANSACTION DATA
# ================================================================

rng = np.random.default_rng(42)


atm_join["Transactions"] = (

    rng.poisson(

        lam=500,

        size=len(atm_join)

    )

    + 100

)


average_amount = rng.uniform(

    700,

    3000,

    len(atm_join)

)


atm_join["Transaction_Amount"] = (

    atm_join["Transactions"]

    *

    average_amount

).round(2)


# ================================================================
# 19. SAME DEMO FRAUD DATA
# ================================================================

atm_join["Base_Risk"] = rng.uniform(

    0.05,

    0.85,

    len(atm_join)

)


fraud_probability = (

    0.003

    +

    atm_join["Base_Risk"]

    *

    0.012

)


fraud_counts = []


for transactions, probability in zip(

    atm_join["Transactions"],

    fraud_probability

):

    fraud_counts.append(

        rng.binomial(

            int(transactions),

            float(probability)

        )

    )


atm_join["Fraud_Count"] = (
    fraud_counts
)


atm_join["Fraud_Rate"] = np.where(

    atm_join["Transactions"] > 0,

    atm_join["Fraud_Count"]
    /
    atm_join["Transactions"],

    0

)


# ================================================================
# 20. ATM RISK SCORE
# ================================================================

def minmax(series):

    values = pd.to_numeric(

        series,

        errors="coerce"

    ).fillna(0).astype(float)


    minimum = values.min()

    maximum = values.max()


    if maximum == minimum:

        return pd.Series(

            np.zeros(
                len(values)
            ),

            index=values.index

        )


    return (

        (values - minimum)
        /
        (maximum - minimum)

    )


atm_fraud_component = minmax(

    atm_join["Fraud_Count"]

)


atm_activity_component = minmax(

    atm_join["Transactions"]

)


atm_join["ATM_Risk_Score"] = (

    0.20
    *
    atm_fraud_component
    *
    100

    +

    0.80
    *
    atm_activity_component
    *
    100

)


atm_join["ATM_Risk_Score"] = (

    atm_join[
        "ATM_Risk_Score"
    ]

    .clip(
        0,
        100
    )

    .round(2)

)


def atm_risk_level(score):

    score = float(score)


    if score >= 66:

        return "HIGH"

    elif score >= 33:

        return "MEDIUM"

    else:

        return "LOW"


atm_join["ATM_Risk_Level"] = (

    atm_join[
        "ATM_Risk_Score"
    ]

    .apply(
        atm_risk_level
    )

)


