#
# Hyderabad           -> Hyderabad
# Cyberabad activity  -> Medchal-Malkajgiri
# Rachakonda activity -> Rangareddy
#
# This is ONLY a demo visualization mapping.
#
# ================================================================


def adjust_urban_activity(row):

    district = normalize_name(

        row[
            gis_district_col
        ]

    )


    current = int(

        row[
            "Crime_Reports"
        ]

    )


    if district == "hyderabad":

        return 20200


    elif district == "medchal malkajgiri":

        return 20500


    elif district == "rangareddy":

        return 23000


    elif district == "yadadri bhuvanagiri":

        return max(
            current,
            2500
        )


    return current


