positive_values = crime_values[

    crime_values > 0

]


if len(positive_values) > 0:

    crime_min = float(
        positive_values.min()
    )

    crime_max = float(
        positive_values.max()
    )

else:

    crime_min = 0

    crime_max = 1


# ================================================================
# 27. CONVERT CRIME COUNT INTO 40 SHADES
# ================================================================

def get_red_shade(crime_count):

    crime_count = float(
        crime_count
    )


    if crime_count <= 0:

        return RED_PALETTE[0]


    if crime_max == crime_min:

        return RED_PALETTE[20]


    normalized = (

        crime_count - crime_min

    ) / (

        crime_max - crime_min

    )


    normalized = max(

        0.0,

        min(
            1.0,
            normalized
        )

    )


    index = int(

        normalized
        *
        (len(RED_PALETTE) - 1)

    )


    return RED_PALETTE[index]


