# ================================================================
# 5. HELPER
# ================================================================

def find_column(df, candidates):

    for c in candidates:

        if c in df.columns:

            return c


    for col in df.columns:

        col_clean = (

            str(col)
            .lower()
            .replace("_", "")
            .replace(" ", "")
            .replace("-", "")

        )


        for candidate in candidates:

            candidate_clean = (

                str(candidate)
                .lower()
                .replace("_", "")
                .replace(" ", "")
                .replace("-", "")

            )


            if (

                candidate_clean == col_clean

                or candidate_clean in col_clean

                or col_clean in candidate_clean

            ):

                return col


    return None


