# ================================================================
# 22. NORMALIZE DISTRICT NAMES
# ================================================================

def normalize_name(name):

    if pd.isna(name):

        return ""


    text = str(name).strip()


    text = text.replace(
        "_",
        " "
    )


    text = text.replace(
        "-",
        " "
    )


    text = re.sub(

        r"\bdistrict\b",

        "",

        text,

        flags=re.IGNORECASE

    )


    text = " ".join(
        text.split()
    )


    return text.lower()


crime_lookup = {

    normalize_name(k): int(v)

    for k, v

    in CRIME_ACTIVITY.items()

}


# ================================================================
# 23. ADD CRIME COUNTS TO DISTRICTS
# ================================================================

telangana["Crime_Reports"] = (

    telangana[
        gis_district_col
    ]

    .apply(
        normalize_name
    )

    .map(
        crime_lookup
    )

    .fillna(0)

    .astype(int)

)


# ================================================================
# 24. URBAN CRIME ADJUSTMENT
# ================================================================

def adjust_urban_activity(row):

    district = normalize_name(

        row[
            gis_district_col
        ]

    )


    current = int(

        row[
            "Crime_Reports"
        ]

    )


    if district == "hyderabad":

        return 20200


    elif district == "medchal malkajgiri":

        return 20500


    elif district == "rangareddy":

        return 23000


    elif district == "yadadri bhuvanagiri":

        return max(
            current,
            2500
        )


    return current


telangana["Crime_Reports"] = (

    telangana

    .apply(

        adjust_urban_activity,

        axis=1

    )

)


