# ================================================================
# 30. NORMALIZE DISTRICT NAMES
# ================================================================

def normalize_name(name):

    if pd.isna(name):

        return ""


    text = str(name).strip()


    text = text.replace(
        "_",
        " "
    )


    text = text.replace(
        "-",
        " "
    )


    text = re.sub(

        r"\bdistrict\b",

        "",

        text,

        flags=re.IGNORECASE

    )


    text = " ".join(
        text.split()
    )


    return text.lower()


