# ================================================================
# 47. ATM COUNT -> BLUE SHADE
# ================================================================

def get_blue_shade(atm_count):

    atm_count = float(
        atm_count
    )


    # ------------------------------------------------------------
    # No ATM
    # ------------------------------------------------------------

    if atm_count <= 0:

        return BLUE_PALETTE[0]


    # ------------------------------------------------------------
    # Same value everywhere
    # ------------------------------------------------------------

    if density_max == density_min:

        return BLUE_PALETTE[20]


    # ------------------------------------------------------------
    # Normalize 0 -> 1
    # ------------------------------------------------------------

    normalized = (

        atm_count - density_min

    ) / (

        density_max - density_min

    )


    normalized = max(

        0.0,

        min(
            1.0,
            normalized
        )

    )


    # ------------------------------------------------------------
    # Map to one of 40 shades
    # ------------------------------------------------------------

    index = int(

        normalized

        *

        (len(BLUE_PALETTE) - 1)

    )


    return BLUE_PALETTE[index]


